import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import type { IntegrationDomain, IntegrationSpec, SandboxCheck } from "../packages/core/src/index.js";
import type { DocMockModule } from "../packages/testkit/src/doc-mock.js";

// The connector registry. Each connector keeps everything about itself in its
// own files; every list that names all of them is generated from those files
// by npm run registry:write, and npm run registry:check (and a test) fails
// when a generated file is out of date. See CONTRIBUTING.md, "Adding a connector".

export class RegistryError extends Error {}

/** Where each connector's own files live, relative to the repository root. */
export const PATHS = {
  connectors: "packages/connectors/src",
  catalog: "packages/core/src/catalog",
  factories: "packages/server/src/connectors",
  mocks: "packages/testkit/src/mocks",
  sandboxChecks: "scripts/sandbox-checks",
  manifest: "secrets/manifest",
  docs: "docs/integrations",
} as const;

/** Files the registry writes. Each is marked as generated; edit the files it is made from instead. */
export const OUTPUTS = {
  connectorsIndex: `${PATHS.connectors}/index.ts`,
  catalogIndex: `${PATHS.catalog}/index.ts`,
  factoriesIndex: `${PATHS.factories}/index.ts`,
  mocksIndex: `${PATHS.mocks}/index.ts`,
  sandboxChecksIndex: `${PATHS.sandboxChecks}/index.ts`,
  manifest: "secrets/manifest.json",
  docs: "docs/integrations.md",
  workflow: ".github/workflows/sandbox-run.yml",
  readme: "README.md",
} as const;

const ID = /^[a-z][a-z0-9_]*$/;
const sorted = (ids: Iterable<string>) => [...ids].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
const header = (from: string) => `// Generated by npm run registry:write from ${from}. Do not edit.\n`;

/** Module ids in a registry folder: each `<id>.ts`, leaving out the generated index and tests. */
export function moduleIds(root: string, dir: string): string[] {
  const path = join(root, dir);
  if (!existsSync(path)) return [];
  return sorted(
    readdirSync(path)
      .filter((file) => file.endsWith(".ts") && !file.endsWith(".test.ts") && file !== "index.ts")
      .map((file) => file.slice(0, -3))
      .filter((id) => {
        if (!ID.test(id)) throw new RegistryError(`${dir}/${id}.ts: a registry file is named after a catalog id (lowercase letters, digits and _)`);
        return true;
      }),
  );
}

/** Folders under packages/connectors/src with an index.ts: each connector, and code they share. */
export function connectorFolders(root: string): string[] {
  const path = join(root, PATHS.connectors);
  return sorted(readdirSync(path).filter((name) => statSync(join(path, name)).isDirectory() && existsSync(join(path, name, "index.ts"))));
}

export function renderConnectorsIndex(folders: readonly string[]): string {
  return header(`the folders in ${PATHS.connectors}`) + sorted(folders).map((f) => `export * from "./${f}/index.js";\n`).join("");
}

/** A folder index that imports each module's default export and lists them under one name. */
function renderDefaults(ids: readonly string[], from: string, typeImport: string, declaration: (list: string) => string): string {
  const list = sorted(ids);
  return [
    header(from).trimEnd(),
    typeImport,
    ...list.map((id) => `import ${id} from "./${id}.js";`),
    "",
    declaration(list.join(", ")),
    "",
  ].join("\n");
}

export function renderCatalogIndex(ids: readonly string[]): string {
  return renderDefaults(
    ids,
    `the <id>.ts files in ${PATHS.catalog}`,
    'import type { ConnectorCatalogEntry } from "../integrations.js";',
    (list) => `/** Each built connector's own catalog fields, by catalog id. */\nexport const CONNECTOR_CATALOG: Readonly<Record<string, ConnectorCatalogEntry>> = { ${list} };`,
  );
}

export function renderFactoriesIndex(ids: readonly string[]): string {
  return renderDefaults(
    ids,
    `the <id>.ts files in ${PATHS.factories}`,
    'import type { ConnectorFactory } from "../connector-factory.js";',
    (list) => `/** How each built connector is made from an instance's settings, by catalog id. */\nexport const FACTORIES: Readonly<Record<string, ConnectorFactory>> = { ${list} };`,
  );
}

export function renderSandboxChecksIndex(ids: readonly string[]): string {
  return renderDefaults(
    ids,
    `the <id>.ts files in ${PATHS.sandboxChecks}`,
    'import type { SandboxCheck } from "@karatos/core";',
    (list) => `/** Every connector's nightly sandbox check. */\nexport const SANDBOX_CHECKS: SandboxCheck[] = [${list}];`,
  );
}

export function renderMocksIndex(ids: readonly string[]): string {
  const list = sorted(ids);
  return renderDefaults(
    list,
    `the <id>.ts files in ${PATHS.mocks}`,
    'import type { DocMock, DocMockModule } from "../doc-mock.js";',
    (names) =>
      [
        ...list.map((id) => `export * from "./${id}.js";`),
        "",
        "/** Every mock module, one per catalog integration. */",
        `export const DOC_MOCK_MODULES: readonly DocMockModule[] = [${names}];`,
        "",
        "/** Every doc-derived mock, with empty data, for checks and the vendor docs watch. */",
        "export function allDocMocks(): DocMock[] {",
        "  return DOC_MOCK_MODULES.flatMap((module) => module.docMocks());",
        "}",
      ].join("\n"),
  );
}

// Secrets manifest. Each connector's settings are in secrets/manifest/<id>.json;
// settings for the instance itself in instance.json; and settings several
// connectors share in shared.json, which each of them names in its own `uses`.

type Entry = { name: string; requiredFor: string[] } & Record<string, unknown>;

export interface ManifestParts {
  instance: { entries: Entry[] };
  shared: { entries: Entry[] };
  connectors: { file: string; data: { integration?: string; uses?: string[]; entries?: Entry[] } }[];
}

export const MANIFEST_COMMENT = "Generated by npm run registry:write from secrets/manifest/*.json. Edit those, not this file.";

export function readManifestParts(root: string): ManifestParts {
  const dir = join(root, PATHS.manifest);
  const read = (file: string) => {
    try {
      return JSON.parse(readFileSync(join(dir, file), "utf8"));
    } catch (error) {
      throw new RegistryError(`${PATHS.manifest}/${file}: ${(error as Error).message}`);
    }
  };
  const files = sorted(readdirSync(dir).filter((f) => f.endsWith(".json") && f !== "instance.json" && f !== "shared.json"));
  return { instance: read("instance.json"), shared: read("shared.json"), connectors: files.map((file) => ({ file, data: read(file) })) };
}

/** The whole manifest: the instance's settings, then the shared ones, then each connector's, sorted by id. */
export function mergeManifest(parts: ManifestParts): { $comment: string; version: 1; entries: Entry[] } {
  const problems: string[] = [];
  const connectors = [...parts.connectors].sort((a, b) => (a.file < b.file ? -1 : 1));
  const own = new Set(connectors.map((c) => c.file.slice(0, -".json".length)));
  for (const entry of parts.instance.entries) {
    for (const scope of entry.requiredFor) {
      if (scope.startsWith("integration:") && own.has(scope.slice(12))) problems.push(`instance.json: ${entry.name} belongs in ${scope.slice(12)}.json`);
    }
  }
  const shared = new Map(parts.shared.entries.map((entry) => [entry.name, { ...entry, requiredFor: [...entry.requiredFor] }]));
  for (const entry of parts.shared.entries) {
    if (entry.requiredFor.some((scope) => scope.startsWith("integration:"))) {
      problems.push(`shared.json: ${entry.name} lists an integration; each connector names it in its own file's uses instead`);
    }
  }
  const entries: Entry[] = [];
  for (const { file, data } of connectors) {
    const id = file.slice(0, -".json".length);
    if (data.integration !== id) problems.push(`${file}: integration must be "${id}"`);
    for (const name of data.uses ?? []) {
      const entry = shared.get(name);
      if (!entry) problems.push(`${file}: uses ${name}, which isn't in shared.json`);
      else if (!entry.requiredFor.includes(`integration:${id}`)) entry.requiredFor.push(`integration:${id}`);
    }
    for (const entry of data.entries ?? []) {
      if (JSON.stringify(entry.requiredFor) !== JSON.stringify([`integration:${id}`])) {
        problems.push(`${file}: ${entry.name} must be requiredFor ["integration:${id}"] only; a setting others need too goes in shared.json`);
      }
      entries.push(entry);
    }
  }
  for (const entry of shared.values()) if (entry.requiredFor.length === 0) problems.push(`shared.json: no connector uses ${entry.name}`);
  const all = [...parts.instance.entries, ...shared.values(), ...entries];
  const seen = new Set<string>();
  for (const entry of all) {
    if (seen.has(entry.name)) problems.push(`${entry.name} is in the manifest twice`);
    seen.add(entry.name);
  }
  if (problems.length) throw new RegistryError(`secrets manifest:\n- ${problems.join("\n- ")}`);
  return { $comment: MANIFEST_COMMENT, version: 1, entries: all };
}

export const renderManifest = (parts: ManifestParts) => `${JSON.stringify(mergeManifest(parts), null, 2)}\n`;

// Generated blocks inside hand-written files, between a start and an end marker line.

export function replaceBlock(text: string, file: string, name: string, lines: (indent: string) => string[]): string {
  const all = text.split("\n");
  const find = (marker: string) => all.flatMap((line, i) => (line.includes(marker) ? [i] : []));
  const starts = find(`registry:${name}:start`);
  const ends = find(`registry:${name}:end`);
  if (starts.length !== 1 || ends.length !== 1 || ends[0]! < starts[0]!) {
    throw new RegistryError(`${file} needs exactly one registry:${name}:start ... registry:${name}:end block`);
  }
  const indent = /^\s*/.exec(all[starts[0]!]!)![0];
  return [...all.slice(0, starts[0]! + 1), ...lines(indent), ...all.slice(ends[0]!)].join("\n");
}

export function renderSandboxEnv(checks: readonly Pick<SandboxCheck, "integration" | "credentials">[]): (indent: string) => string[] {
  const list = [...checks].sort((a, b) => (a.integration < b.integration ? -1 : 1));
  return (indent) => [
    `${indent}# Generated by npm run registry:write from each check in scripts/sandbox-checks/. Edit those, not this block.`,
    ...list.flatMap((check) => check.credentials.map((name) => `${indent}${name}: \${{ secrets.${name} }}`)),
  ];
}

/** Which table in docs/integrations.md each kind of system goes in, in the order the tables appear. */
export const CATALOG_SECTIONS: readonly { title: string; domains: readonly IntegrationDomain[] }[] = [
  { title: "Point of sale and e-commerce", domains: ["pos", "ecommerce"] },
  { title: "Diamonds, suppliers and grading", domains: ["diamonds", "suppliers", "grading"] },
  { title: "Pricing", domains: ["pricing"] },
  { title: "Customers, marketing and communication", domains: ["crm", "communication", "documents", "marketing"] },
  { title: "Money", domains: ["financial"] },
  { title: "Manufacturing and wholesale operations", domains: ["erp", "edi", "insurance", "shipping"] },
];

const ACCESS: Record<IntegrationSpec["access"], string> = { public_api: "Public API", partner: "Partner", edi: "EDI", file: "File export", unknown: "Unknown" };
const TEST_WITH: Record<IntegrationSpec["testWith"], string> = {
  sandbox: "Free sandbox",
  fixtures: "Sample files",
  paid_account: "Paid account",
  partner: "Partner",
  unknown: "Unknown",
};
const STATUS: Record<IntegrationSpec["status"], string> = { built: "Built", planned: "Planned", deferred: "Deferred" };
const SEGMENTS = ["retail", "wholesale", "manufacturing"] as const;

export function renderCatalogTables(catalog: readonly IntegrationSpec[]): string[] {
  const placed = new Set(CATALOG_SECTIONS.flatMap((s) => s.domains));
  const unplaced = catalog.filter((i) => !placed.has(i.domain)).map((i) => i.id);
  if (unplaced.length) throw new RegistryError(`no docs table for ${unplaced.join(", ")}; add its domain to CATALOG_SECTIONS`);
  const row = (i: IntegrationSpec) =>
    `| ${i.name} | ${SEGMENTS.filter((s) => i.segments.includes(s)).map((s) => s[0]!.toUpperCase()).join(", ")} | ${ACCESS[i.access]} | ${TEST_WITH[i.testWith]} | ${i.webhooks ? "Yes" : "No"} | ${STATUS[i.status]}${i.note ? ` (${i.note})` : ""} |`;
  return [
    "<!-- Generated from packages/core/src/integrations.ts and each connector's packages/core/src/catalog/<id>.ts by npm run registry:write. Edit those, not this block. -->",
    ...CATALOG_SECTIONS.flatMap((section) => [
      "",
      `### ${section.title}`,
      "",
      "| Integration | Used by | Access | Test with | Webhooks | Status |",
      "| --- | --- | --- | --- | --- | --- |",
      ...catalog.filter((i) => section.domains.includes(i.domain)).map(row),
    ]),
    "",
  ];
}

const andList = (items: readonly string[]) => (items.length < 2 ? items.join("") : `${items.slice(0, -1).join(", ")} and ${items.at(-1)}`);

export function renderMockList(modules: readonly Pick<DocMockModule, "integration" | "covers">[], catalog: readonly IntegrationSpec[]): string[] {
  const list = [...modules].sort((a, b) => (a.integration < b.integration ? -1 : 1));
  const spec = (id: string) => catalog.find((i) => i.id === id);
  const sandbox = list.filter((m) => spec(m.integration)?.testWith === "sandbox").map((m) => spec(m.integration)!.name);
  return [
    "<!-- Generated from the mock modules in packages/testkit/src/mocks/ by npm run registry:write. Edit those, not this block. -->",
    "",
    ...list.map((m) => `- ${m.covers}`),
    ...(sandbox.length ? ["", `Where a vendor has a free sandbox (${andList(sandbox)} so far), its mock is a stand-in until a developer account is set up for the nightly run.`] : []),
    "",
  ];
}

export function renderConnectorDocs(sections: readonly { id: string; text: string }[]): string[] {
  const list = [...sections].sort((a, b) => (a.id < b.id ? -1 : 1));
  for (const { id, text } of list) {
    if (!text.startsWith("### ")) throw new RegistryError(`${PATHS.docs}/${id}.md must start with its "### " heading`);
  }
  return [
    "<!-- Generated from docs/integrations/<id>.md by npm run registry:write. Edit those, not this block. -->",
    ...list.flatMap(({ text }) => ["", ...text.trimEnd().split("\n")]),
    "",
  ];
}

export function readConnectorDocs(root: string): { id: string; text: string }[] {
  const dir = join(root, PATHS.docs);
  return sorted(readdirSync(dir).filter((f) => f.endsWith(".md")))
    .map((file) => ({ id: file.slice(0, -3), text: readFileSync(join(dir, file), "utf8") }));
}

/** Generated files that are made from the folders alone, without loading any connector code. */
export function generateFromFiles(root: string): Map<string, string> {
  return new Map([
    [OUTPUTS.connectorsIndex, renderConnectorsIndex(connectorFolders(root))],
    [OUTPUTS.catalogIndex, renderCatalogIndex(moduleIds(root, PATHS.catalog))],
    [OUTPUTS.factoriesIndex, renderFactoriesIndex(moduleIds(root, PATHS.factories))],
    [OUTPUTS.mocksIndex, renderMocksIndex(moduleIds(root, PATHS.mocks))],
    [OUTPUTS.sandboxChecksIndex, renderSandboxChecksIndex(moduleIds(root, PATHS.sandboxChecks))],
    [OUTPUTS.manifest, renderManifest(readManifestParts(root))],
  ]);
}

const load = async <T>(root: string, file: string): Promise<T> => (await import(pathToFileURL(join(root, file)).href)).default as T;

/** Each module's default export in a registry folder, checked to be the one its file name says. */
async function loadModules<T extends { integration: string }>(root: string, dir: string): Promise<T[]> {
  const modules: T[] = [];
  for (const id of moduleIds(root, dir)) {
    const module = await load<T>(root, `${dir}/${id}.ts`);
    if (module?.integration !== id) throw new RegistryError(`${dir}/${id}.ts: its default export must be for integration "${id}"`);
    modules.push(module);
  }
  return modules;
}

/**
 * Generated blocks that need the catalog, the mocks and the sandbox checks
 * themselves. Run after generateFromFiles has been written, since the
 * catalog is read through the index it writes.
 */
export async function generateFromModules(root: string, read: (file: string) => string): Promise<Map<string, string>> {
  const { INTEGRATIONS } = (await import(pathToFileURL(join(root, "packages/core/src/index.ts")).href)) as { INTEGRATIONS: IntegrationSpec[] };
  const { MILESTONES, parseMilestones, renderProgress, replaceProgress } = await import("./progress.js");
  const mocks = await loadModules<DocMockModule>(root, PATHS.mocks);
  const checks = await loadModules<SandboxCheck>(root, PATHS.sandboxChecks);
  let docs = read(OUTPUTS.docs);
  docs = replaceBlock(docs, OUTPUTS.docs, "catalog", () => renderCatalogTables(INTEGRATIONS));
  docs = replaceBlock(docs, OUTPUTS.docs, "mocks", () => renderMockList(mocks, INTEGRATIONS));
  docs = replaceBlock(docs, OUTPUTS.docs, "connector-docs", () => renderConnectorDocs(readConnectorDocs(root)));
  const progress = renderProgress(parseMilestones(JSON.parse(read(MILESTONES)), INTEGRATIONS), INTEGRATIONS);
  return new Map([
    [OUTPUTS.docs, docs],
    [OUTPUTS.workflow, replaceBlock(read(OUTPUTS.workflow), OUTPUTS.workflow, "sandbox-env", renderSandboxEnv(checks))],
    [OUTPUTS.readme, replaceProgress(read(OUTPUTS.readme), progress)],
  ]);
}

/** Generated files whose content on disk differs from what the registry makes. */
export function stale(expected: ReadonlyMap<string, string>, read: (file: string) => string | null): string[] {
  return [...expected].filter(([file, content]) => read(file) !== content).map(([file]) => file);
}
